mapper.select:
/* MobCargoMapper.checkCargoListByBlNo : 화물조회 - BL 중복체크 */
SELECT 'IN' AS dGbn ,ISNULL(SUBSTRING(AR_DATE,3,8), '') AS AR_DATE_TIME ,ISNULL(SUBSTRING(CARRYIN_DATE,3,8) + ' ' + CARRYIN_TIME, '') AS CARRYIN_DATE_TIME ,CASE WHEN IN_CLASS = '10' THEN '입항' WHEN IN_CLASS = '21' THEN '이고' WHEN IN_CLASS = '20' THEN '보운' ELSE '기타' END AS IN_CLASS_NAME ,IN_NO AS IN_NO ,IN_PLAN_NO AS IN_PLAN_NO ,OD_JOB_NO FROM TB_BMS_IN WITH (NOLOCK) WHERE BL_NO = #{hblNo}
UNION ALL SELECT 'IN_PLAN' AS dGbn ,ISNULL(SUBSTRING(AR_DATE,3,8), '') AS AR_DATE_TIME ,'' AS CARRYIN_DATE_TIME ,'' AS IN_CLASS_NM ,0 AS IN_NO ,IN_PLAN_NO AS IN_PLAN_NO ,OD_JOB_NO FROM TB_BMS_IN_PLAN WITH (NOLOCK) WHERE BL_NO = #{hblNo} AND IN_YN = 'N'
UNION ALL SELECT 'ORDER' AS dGbn ,ISNULL(SUBSTRING(CONVERT(VARCHAR,AR_DATE,21),3,8), '') AS AR_DATE_TIME ,'' AS CARRYIN_DATE_TIME ,'' AS IN_CLASS_NM ,0 AS IN_NO ,0 AS IN_PLAN_NO ,OD_JOB_NO FROM TB_ECM_OD WHERE HBL_NO = #{hblNo}
